package com.aditya.chat.websocket; import com.aditya.chat.dto.MessageRequest; import com.aditya.chat.entity.ChatMessage; import com.aditya.chat.service.MessageService; import org.springframework.messaging.handler.annotation.MessageMapping; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Controller; import java.security.Principal; @Controller public class ChatWebSocketController{final SimpMessagingTemplate messaging;final MessageService service;public ChatWebSocketController(SimpMessagingTemplate m,MessageService s){messaging=m;service=s;}@MessageMapping("/chat.send")public void send(MessageRequest r,Principal p){ChatMessage m=service.save(p.getName(),r);messaging.convertAndSend("/topic/chat/"+r.chatId(),m);}@MessageMapping("/chat.typing")public void typing(MessageRequest r,Principal p){messaging.convertAndSend("/topic/chat/"+r.chatId()+"/typing",p.getName());}}
